SELECT * FROM biz_info



        WHERE receiver_id = #{otherId}
        AND receiver_type = 1



        WHERE ((receiver_id = #{userId} AND sender_id = #{otherId})
        OR  (sender_id = #{userId} AND receiver_id = #{otherId}))
